import { type } from "arktype";

/**
 * Runtime-validated resolved response shape.
 *
 * This `Type` is applied to the value that the simulated network call
 * resolves with, so the runtime resolution is guaranteed to satisfy the
 * declared contract (see hint in the task spec).
 */
export const response = type({
  status: "number.integer >= 100 <= 599",
  body: "string"
});

/**
 * Parameter shape enforced synchronously at the `type.fn` boundary, BEFORE
 * any asynchronous work (i.e. before `setTimeout` is scheduled).
 */
const params = type({
  url: "string.url",
  timeoutMs: "number.integer > 0 <= 10000",
  retries: "number.integer >= 0 <= 5"
});

/**
 * A runtime-validated asynchronous fetch wrapper built with ArkType's
 * `type.fn`.
 *
 * - The parameter shape is validated synchronously by `type.fn` when the
 *   wrapper is invoked. Invalid params throw before any `setTimeout` is
 *   created.
 * - The (Promise) return shape is enforced by `type.fn`'s return type
 *   (`"Promise"`), which asserts the implementation returns a `Promise`
 *   instance.
 * - The resolved value is validated against {@link response} inside the
 *   implementation before the promise resolves.
 *
 * The simulated network call ALWAYS resolves with
 * `{ status: 200, body: "ok" }` after `min(timeoutMs, 50)` milliseconds.
 */
export const fetchWithTimeout = type.fn(params, ":", "Promise")(
  async (p) => {
    const delay = Math.min(p.timeoutMs, 50);
    return await new Promise((resolve) => {
      setTimeout(() => {
        // Validate the resolved value against the declared response Type
        // so the runtime resolution is guaranteed to satisfy the contract.
        resolve(response.assert({ status: 200, body: "ok" }));
      }, delay);
    });
  }
);

import { fetchWithTimeout } from "./src/validator.js";

/**
 * Read the entire stdin stream as a UTF-8 string.
 */
function readStdin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk: string) => {
      data += chunk;
    });
    process.stdin.on("end", () => resolve(data));
    process.stdin.on("error", reject);
  });
}

/**
 * Extract a non-empty, human-readable description from any thrown value.
 *
 * ArkType validation failures throw a `TraversalError` (an `Error` subclass
 * whose `message` is the `ArkErrors.summary`). We fall back gracefully for
 * any other thrown shape.
 */
function describeError(e: unknown): string {
  if (e !== null && typeof e === "object") {
    const summary = (e as { summary?: unknown }).summary;
    if (typeof summary === "string" && summary.length > 0) {
      return summary;
    }
  }
  if (e instanceof Error && e.message) {
    return e.message;
  }
  const s = String(e);
  return s || "validation failed";
}

async function main(): Promise<void> {
  let input: string;
  try {
    input = await readStdin();
  } catch (e) {
    process.stdout.write(`ERR ${describeError(e)}\n`);
    return;
  }

  let result: unknown;
  try {
    let doc: unknown;
    try {
      doc = JSON.parse(input);
    } catch (e) {
      throw new Error(`invalid JSON input: ${describeError(e)}`);
    }

    if (doc === null || typeof doc !== "object" || Array.isArray(doc)) {
      throw new Error("input must be a JSON object with a \"params\" field");
    }

    const params = (doc as { params?: unknown }).params;
    if (params === undefined) {
      throw new Error("input must be a JSON object with a \"params\" field");
    }

    // `await` captures both synchronous throws (parameter validation at the
    // type.fn boundary) and rejected promises (resolved-value validation).
    result = await fetchWithTimeout(params);
  } catch (e) {
    process.stdout.write(`ERR ${describeError(e)}\n`);
    return;
  }

  process.stdout.write(`OK ${JSON.stringify(result)}\n`);
}

// Always exit with code 0 for both success and validation-failure paths.
main().then(
  () => process.exit(0),
  (e) => {
    // Should not normally happen, but guard against unexpected rejections.
    process.stdout.write(`ERR ${describeError(e)}\n`);
    process.exit(0);
  }
);

